const originalBody = $('1. Webhook - Nouvel Avis').first().json.body;

function extractScore(text, regex, def = 7) {
  const m = (text || '').match(new RegExp(regex, 'i'));
  return m ? Math.max(1, Math.min(10, parseInt(m[1]))) : def;
}

let foodResp = '', servResp = '', priceResp = '', ambResp = '';
try { foodResp = $('2A. Mistral Expert Food 🍔').first().json.response || ''; } catch(e){}
try { servResp = $('2B. Mistral Expert Service 🤝').first().json.response || ''; } catch(e){}
try { priceResp = $('2C. Mistral Expert Prix 💶').first().json.response || ''; } catch(e){}
try { ambResp = $('2D. Mistral Expert Ambiance 🏠').first().json.response || ''; } catch(e){}

const foodScore = extractScore(foodResp, 'FOOD_SCORE[:\\s\\-]+(\\d+)', 8);
const serviceScore = extractScore(servResp, 'SERVICE_SCORE[:\\s\\-]+(\\d+)', 7);
const priceScore = extractScore(priceResp, 'PRICE_SCORE[:\\s\\-]+(\\d+)', 6);
const ambianceScore = extractScore(ambResp, 'AMBIANCE_SCORE[:\\s\\-]+(\\d+)', 8);

return [{
  json: {
    status: "success",
    restaurant: originalBody.restaurant || 'Restaurant',
    review: originalBody.review,
    multi_criteria_scores: {
      food: foodScore,
      service: serviceScore,
      price: priceScore,
      ambiance: ambianceScore
    },
    rating: originalBody.rating || '5',
    chain_of_thought_reasoning: {
      food_thought: foodResp,
      service_thought: servResp,
      price_thought: priceResp,
      ambiance_thought: ambResp
    }
  }
}];
